/*"selectBuyerMdAmNoticeManageList"*/ SELECT * FROM (SELECT /*+ index_asc(BUYERBOARD CUSTBOARD_pk) */ A.BID, A.COM_CODE, A.SUBJECT, (SELECT EMAIL FROM ICOMLUSR WHERE USER_ID = A.REG_USER_ID) EMAIL, A.REG_DATE, (SELECT MAX (VID) FROM BUYERBOARD WHERE BYCA_COMORG_CODE = A.BYCA_COMORG_CODE AND STATUS != 'D' AND BTYPE = 'NTC'
AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN FROM_DATE AND TO_DATE
) MAX_VID, (SELECT MIN (VID) FROM BUYERBOARD WHERE BYCA_COMORG_CODE = A.BYCA_COMORG_CODE AND STATUS != 'D' AND BTYPE = 'NTC'
AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN FROM_DATE AND TO_DATE
) MIN_VID, A.ACL, A.LCOUNT, DECODE (A.BTYPE, 'NOR', '일반', 'NTC', '공지') BTYPE_DIS, DECODE (A.ACL, 'INC', '자사', 'BUY', '구매사', 'SEL', '판매사', 'KEP', 'KEP', 'MEB', '회원전체', 'CST', '특정회사', 'UST', '특정사용자', 'ALL', '전체') ACL_DIS, A.BTYPE, A.TO_DATE, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.COM_CODE) COM_NAME_LOC, A.BLEVEL, A.VID, A.OPEN_FLAG, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.REG_USER_ID AND STATUS <> 'D') AS USER_NAME_LOC, A.IMAGE_KEY, A.REG_USER_ID, A.SORT, A.REG_TIME AS REG_TIME, (SELECT OPEN_FLAG FROM BUYERBOARD WHERE BYCA_COMORG_CODE = A.BYCA_COMORG_CODE AND BID = A.PID AND BLEVEL = 0) AS PID_OPEN_FLAG, (SELECT REG_USER_ID FROM BUYERBOARD WHERE BYCA_COMORG_CODE = A.BYCA_COMORG_CODE AND BID = A.PID AND BLEVEL = 0) AS PID_REG_USER_ID, A.BYCA_COMORG_CODE AS BYCA_COMORG_CODE FROM BUYERBOARD A WHERE A.STATUS != 'D' AND A.BYCA_COMORG_CODE = #{st_byca_comorg_code} AND A.BTYPE = 'NTC'
AND TO_CHAR(SYSDATE,'YYYYMMDD') BETWEEN A.FROM_DATE AND A.TO_DATE
AND A.SUBJECT LIKE '%'||#{st_search_word}||'%'
AND DBMS_LOB.INSTR(A.CONTEXT, #{st_search_word}) > 0
AND A.REG_USER_ID IN (SELECT USER_ID FROM ICOMLUSR WHERE USER_NAME_LOC LIKE '%'||#{st_search_word}||'%' AND STATUS <> 'D')
) P ORDER BY 1 DESC

