/*updateNoticeLCount*/
UPDATE BUYERBOARD
   SET LCOUNT = LCOUNT + 1
 WHERE STATUS <> 'D' AND BID = #{BID} AND BTYPE = #{BTYPE} AND BYCA_COMORG_CODE = #{st_byca_comorg_code}


/*updateDetailList*/
UPDATE BUYERBOARD
   SET CONTEXT = #{CONTEXT}, SUBJECT = #{SUBJECT}, IMAGE_KEY = #{IMAGE_KEY}
 WHERE BID = #{BID} AND BTYPE = #{BTYPE} AND BYCA_COMORG_CODE = #{st_byca_comorg_code}


/*deleteDetailList*/
DELETE FROM BUYERBOARD
 WHERE BID = #{BID} AND BTYPE = #{BTYPE} AND BYCA_COMORG_CODE = #{st_byca_comorg_code}
